/**
 * Runtime configuration and site-root resolution.
 *
 * `assets/js/config.js` is GENERATED by `npm run build` from `.env` and is
 * gitignored, so no project reference or key is recorded in git history. When
 * it is absent (fresh clone, offline preview) the app runs in a clearly
 * labelled demo mode instead of showing a blank page.
 *
 * Site root matters because this project is served from a GitHub Pages
 * *project* site, i.e. under `/Muna-havens/`. Every asset path, image path and
 * share link is resolved against it rather than assumed to be `/`.
 */

/** Declared once per HTML document as <meta name="mh-root" content="./">. */
function declaredRoot() {
  const meta = document.querySelector('meta[name="mh-root"]');
  return meta ? meta.getAttribute('content') || './' : './';
}

/**
 * Absolute URL of the directory that contains index.html, e.g.
 * `https://user.github.io/Muna-havens/`. Resolving `./` from the *document*
 * URL gives the right answer for both `/Muna-havens/` (root page) and
 * `/Muna-havens/owner/` (dashboard, which declares `../`).
 */
export function siteRoot() {
  try {
    const url = new URL(declaredRoot(), document.baseURI);
    // Drop a trailing index.html if a browser reports one in baseURI.
    url.hash = '';
    url.search = '';
    let path = url.pathname;
    if (path.endsWith('/owner/')) path = path.slice(0, -'owner/'.length);
    else if (path.endsWith('index.html')) path = path.replace(/index\.html$/, '');
    else if (!path.endsWith('/')) path = path.replace(/[^/]*$/, '');
    url.pathname = path;
    return url.href;
  } catch {
    return document.baseURI;
  }
}

/** Site root with no trailing slash, for building shareable links. */
export function siteOrigin() {
  return siteRoot().replace(/\/+$/, '');
}

/** Resolve a repo-relative asset path (`assets/img/x.svg`) to an absolute URL. */
export function assetUrl(relativePath) {
  const raw = String(relativePath || '').trim();
  if (!raw) return '';
  if (/^(https?:|data:|blob:)/i.test(raw)) return raw;
  try {
    return new URL(raw.replace(/^\.?\/+/, ''), siteRoot()).href;
  } catch {
    return raw;
  }
}

export function readWindowConfig() {
  return (typeof window !== 'undefined' && window.MUNA_HAVEN_CONFIG) || null;
}

/**
 * @returns {{mode:'supabase'|'demo', supabaseUrl:string|null, anonKey:string|null,
 *            siteUrl:string, realtime:boolean, generatedAt:string|null, reason:string}}
 */
export function loadConfig() {
  const cfg = readWindowConfig();
  const supabaseUrl = cleanUrl(cfg && cfg.supabaseUrl);
  const anonKey = (cfg && cfg.supabaseAnonKey ? String(cfg.supabaseAnonKey) : '').trim();
  const hasSupabase = Boolean(supabaseUrl && anonKey);

  return {
    mode: hasSupabase ? 'supabase' : 'demo',
    supabaseUrl,
    anonKey: hasSupabase ? anonKey : null,
    realtime: Boolean(hasSupabase && cfg && cfg.realtime),
    siteUrl: (cfg && cleanUrl(cfg.siteUrl)) || siteOrigin(),
    generatedAt: (cfg && cfg.generatedAt) || null,
    reason: hasSupabase ? 'configured' : 'missing-config',
  };
}

/** Reject anything that is not a http(s) URL, so a typo cannot become an origin. */
function cleanUrl(value) {
  if (!value) return null;
  const raw = String(value).trim().replace(/\/+$/, '');
  if (!raw) return null;
  try {
    const u = new URL(raw);
    if (u.protocol !== 'https:' && u.protocol !== 'http:') return null;
    if (!u.hostname) return null;
    return u.origin + (u.pathname === '/' ? '' : u.pathname.replace(/\/+$/, ''));
  } catch {
    return null;
  }
}
